import{_ as r,a0 as l,w as s,s as p,ao as u,I as o,x as t,a1 as i,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Linux 有問必答：在 Linux 如何更改文本文件的字符編碼 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有問必答：在 Linux 如何更改文本文件的字符編碼 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有問必答：在 Linux 如何更改文本文件的字符編碼 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有問必答：在 Linux 如何更改文本文件的字符編碼 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141022 Linux FAQs with Answers--How to change character encoding of a text file on Linux","title":"Linux 有問必答：在 Linux 如何更改文本文件的字符編碼","tag":"201411","desc":""},"relativePath":"201411/20141022 Linux FAQs with Answers--How to change character encoding of a text file on Linux.md","filePath":"[post].md"}'),x={name:"201411/20141022 Linux FAQs with Answers--How to change character encoding of a text file on Linux.md"};function d(f,e,c,m,h,L){const n=l("Link");return s(),p("div",null,[e[11]||(e[11]=u(`<h1 id="linux-有問必答-在-linux-如何更改文本文件的字符編碼" tabindex="-1">Linux 有問必答：在 Linux 如何更改文本文件的字符編碼 <a class="header-anchor" href="#linux-有問必答-在-linux-如何更改文本文件的字符編碼" aria-label="Permalink to “Linux 有問必答：在 Linux 如何更改文本文件的字符編碼”">​</a></h1><blockquote><p><strong>問題</strong>：在我的 Linux 系統中有一個編碼為 iso-8859-1 的字幕文件，其中部分字符無法正常顯示，我想把文本改為 utf8 編碼。在 Linux 中, 有沒有一個好的工具來轉換文本文件的字符編碼？</p></blockquote><p>正如我們所知道的那樣，電腦只能夠處理低級的二進制值，並不能直接處理字符。當一個文本文件被存儲時，文件中的每一個字符都被映射成二進制值，實際存儲在硬盤中的正是這些“二進制值”。之後當程序打開文本文件時，所有二進制值都被讀入並映射回原始的可讀字符。只有當所有需要訪問這個文件的程序都能夠“理解”它的編碼，即二進制值到字符的映射時，這個“保存和打開”的過程才能很好地完成，這也確保了可理解數據的往返過程。</p><p>如果不同的程序使用不同的編碼來處理同一個文件，源文件中的特殊字符就無法正常顯示。這裏的特殊字符指的是非英文字母的字符，例如帶重音的字符（比如 ñ，á，ü）。</p><p>然後問題就來了： 1）我們如何確定一個確定的文本文件使用的是什麼字符編碼？ 2）我們如何把文件轉換成已選擇的字符編碼？</p><h3 id="步驟一" tabindex="-1">步驟一 <a class="header-anchor" href="#步驟一" aria-label="Permalink to “步驟一”">​</a></h3><p>為了確定文件的字符編碼，我們使用一個名為 “file” 的命令列工具。因為 file 命令是一個標準的 UNIX 程序，所以我們可以在所有現代的 Linux 發行版中找到它。</p><p>運行下面的命令：</p><pre><code>$ file --mime-encoding filename 
</code></pre><p><img src="https://farm6.staticflickr.com/5602/15595534261_1a7b4d16a2.jpg" alt=""></p><h3 id="步驟二" tabindex="-1">步驟二 <a class="header-anchor" href="#步驟二" aria-label="Permalink to “步驟二”">​</a></h3><p>下一步是查看你的 Linux 系統所支持的文件編碼種類。為此，我們使用名為 iconv 的工具及 “-l” 選項（L 的小寫）來列出所有當前支持的編碼。</p><pre><code>$ iconv -l 
</code></pre><p>iconv 工具是 GNU libc 庫組成部分，因此它在所有 Linux 發行版中都是開箱即用的。</p><h3 id="步驟三" tabindex="-1">步驟三 <a class="header-anchor" href="#步驟三" aria-label="Permalink to “步驟三”">​</a></h3><p>在我們在我們的 Linux 系統所支持的編碼裏面選定了目標編碼之後，運行下面的命令來完成編碼轉換：</p><pre><code>$ iconv -f old_encoding -t new_encoding filename
</code></pre><p>例如，把 iso-8859-1 編碼轉換為 utf-8 編碼：</p><pre><code>$ iconv -f iso-8859-1 -t utf-8 input.txt 
</code></pre><p><img src="https://farm4.staticflickr.com/3943/14978042143_a516e0b10b_o.png" alt=""></p><p>瞭解了我們演示的如何使用這些工具之後，你可以像下面這樣修復一個受損的字幕文件：</p><p><img src="https://farm6.staticflickr.com/5612/15412197967_0dfe5078f9_z.jpg" alt=""></p><hr>`,23)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),i(n,{href:"http://ask.xmodulo.com/change-character-encoding-text-file-linux.html"},{default:a(()=>[...e[0]||(e[0]=[t("http://ask.xmodulo.com/change-character-encoding-text-file-linux.html",-1)])]),_:1})]),o("p",null,[e[4]||(e[4]=t("譯者：",-1)),i(n,{href:"https://github.com/wangjiezhe"},{default:a(()=>[...e[2]||(e[2]=[t("wangjiezhe",-1)])]),_:1}),e[5]||(e[5]=t(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:a(()=>[...e[3]||(e[3]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[8]||(e[8]=t("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原創翻譯，",-1)),i(n,{href:"http://linux.cn/"},{default:a(()=>[...e[7]||(e[7]=[t("Linux中國",-1)])]),_:1}),e[10]||(e[10]=t(" 榮譽推出",-1))])])}const w=r(x,[["render",d]]);export{T as __pageData,w as default};
